export interface HubNavigationTarget {
  projectId?: string;
  sessionId?: string;
  variantId?: string;
}
export interface HubNavigationRequest extends HubNavigationTarget {
  requestId: string;
}
export interface HubViewNavigation extends HubNavigationRequest {
  sequence: number;
}
interface NavigationResult {
  handled: boolean;
}
interface View {
  lastSeen: number;
  lastFocused: number;
}
interface PendingNavigation {
  navigation: HubViewNavigation;
  viewId: string;
  finish: (result: NavigationResult) => void;
  timer: NodeJS.Timeout;
}
const VIEW_TIMEOUT_MS = 10_000;
const ACK_TIMEOUT_MS = 2_000;
const REQUEST_HISTORY_LIMIT = 500;

export class HubNavigation {
  private sequence = 0;
  private readonly views = new Map<string, View>();
  private readonly requests = new Map<string, Promise<NavigationResult>>();
  private readonly pendingRequests = new Map<number, PendingNavigation>();

  connect({ viewId, isFocused }: { viewId: string; isFocused: boolean }): void {
    const now = Date.now();
    this.views.set(viewId, {
      lastSeen: now,
      lastFocused: isFocused ? now : (this.views.get(viewId)?.lastFocused ?? 0),
    });
  }

  request(request: HubNavigationRequest): Promise<NavigationResult> {
    const existing = this.requests.get(request.requestId);
    if (existing) return existing;
    const now = Date.now();
    const selected = [...this.views.entries()]
      .filter(([, view]) => now - view.lastSeen < VIEW_TIMEOUT_MS)
      .sort(
        (a, b) =>
          b[1].lastFocused - a[1].lastFocused || b[1].lastSeen - a[1].lastSeen,
      )[0];
    if (!selected) return Promise.resolve({ handled: false });
    const sequence = ++this.sequence;
    const promise = new Promise<NavigationResult>((resolve) => {
      const timer = setTimeout(() => {
        this.pendingRequests.delete(sequence);
        resolve({ handled: false });
      }, ACK_TIMEOUT_MS);
      this.pendingRequests.set(sequence, {
        navigation: { ...request, sequence },
        viewId: selected[0],
        finish: resolve,
        timer,
      });
    });
    this.requests.set(request.requestId, promise);
    if (this.requests.size > REQUEST_HISTORY_LIMIT) {
      const oldestRequestId = this.requests.keys().next().value;
      if (oldestRequestId !== undefined) this.requests.delete(oldestRequestId);
    }
    return promise;
  }

  pending(viewId: string): HubViewNavigation[] {
    return [...this.pendingRequests.values()]
      .filter((request) => request.viewId === viewId)
      .map((request) => request.navigation);
  }

  acknowledge(viewId: string, sequence: number): boolean {
    const pending = this.pendingRequests.get(sequence);
    if (!pending || pending.viewId !== viewId) return false;
    clearTimeout(pending.timer);
    this.pendingRequests.delete(sequence);
    pending.finish({ handled: true });
    return true;
  }

  close(): void {
    for (const pending of this.pendingRequests.values()) {
      clearTimeout(pending.timer);
      pending.finish({ handled: false });
    }
    this.pendingRequests.clear();
  }
}
